<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\{BelongsTo,HasMany}; class PaperAnalysis extends Model {protected $guarded=[]; protected function casts():array{return ['structure'=>'array','methodology'=>'array','keywords'=>'array'];} public function paper():BelongsTo{return $this->belongsTo(Paper::class);} public function scores():HasMany{return $this->hasMany(PaperScore::class);} public function findings():HasMany{return $this->hasMany(PaperFinding::class);}}